begin;
insert into auth.users(id,email) values ('99999999-9999-4999-8999-999999999991','attributes@example.com'),('99999999-9999-4999-8999-999999999992','other-attributes@example.com');
do $$ declare
 u uuid:='99999999-9999-4999-8999-999999999991';other uuid:='99999999-9999-4999-8999-999999999992';g uuid:=gen_random_uuid();
 r jsonb;city bigint;count_id bigint;select_id bigint;multi bigint;disabled bigint;required_id bigint;
begin
 r:=public.s2a_attribute_definition_save(null,'{"key":"city","name":"City","type":"text","enabled":true,"validation":{"pattern":"^[[:alpha:] ]+$","message":"Letters only"}}');city:=(r->>'id')::bigint;
 if city is null then raise exception 'create failed %',r;end if;
 r:=public.s2a_attribute_definition_save(null,'{"key":"city","name":"Duplicate","type":"text"}');if r->>'status'<>'409' then raise exception 'duplicate key accepted';end if;
 r:=public.s2a_attribute_definition_save(city,'{"name":"Changed","validation":{"pattern":"["}}');if r->>'error'<>'invalid_attribute_pattern' or (select name from public.s2a_attribute_definitions where id=city)<>'City' then raise exception 'invalid pattern partially saved';end if;
 r:=public.s2a_attribute_definition_save(city,'{"validation":{"max_length":-1}}');if r->>'status'<>'400' then raise exception 'negative length allowed';end if;
 r:=public.s2a_attribute_definition_save(null,'{"key":"count","name":"Count","type":"number","enabled":true}');count_id:=(r->>'id')::bigint;
 r:=public.s2a_attribute_definition_save(null,'{"key":"choice","name":"Choice","type":"select","enabled":true,"options":[{"value":"a","label":"A"},{"value":"b","label":"B"}]}');select_id:=(r->>'id')::bigint;
 r:=public.s2a_attribute_definition_save(null,'{"key":"choices","name":"Choices","type":"multi_select","enabled":true,"options":[{"value":"a","label":"A"},{"value":"b","label":"B"}]}');multi:=(r->>'id')::bigint;
 r:=public.s2a_attribute_definition_save(null,'{"key":"disabled","name":"Disabled","type":"text"}');disabled:=(r->>'id')::bigint;
 r:=public.s2a_attribute_definition_save(null,'{"key":"required","name":"Required","type":"text","required":true,"enabled":true,"validation":{"min_length":2,"max_length":3}}');required_id:=(r->>'id')::bigint;
 r:=public.s2a_attribute_reorder(array[multi,city]);if r ? 'error' or (select display_order from public.s2a_attribute_definitions where id=multi)<>0 or (select display_order from public.s2a_attribute_definitions where id=city)<>1 then raise exception 'reorder failed %',r;end if;
 r:=public.s2a_attribute_reorder(array[city,city]);if r->>'status'<>'400' then raise exception 'duplicate reorder accepted';end if;
 r:=public.s2a_attribute_reorder(array[city,9223372036854775807]);if r->>'status'<>'404' or (select display_order from public.s2a_attribute_definitions where id=city)<>1 then raise exception 'partial reorder';end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(city,'Shanghai',count_id,'42',select_id,'a',multi,'["a","b"]'));if r ? 'error' then raise exception 'save failed %',r;end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(city,'Changed',count_id,'9223372036854775808'));if r->>'status'<>'400' or (select value from public.s2a_attribute_values where user_id=u and attribute_id=city)<>'Shanghai' then raise exception 'overflow or atomicity failed %',r;end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(count_id,'1.5'));if r->>'status'<>'400' then raise exception 'decimal accepted';end if;
 perform public.s2a_attribute_definition_save(count_id,'{"validation":{"min":-2,"max":10}}');
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(count_id,'11'));if r->>'status'<>'400' then raise exception 'numeric bound ignored';end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(count_id,'-2',multi,'a, b'));if r ? 'error' then raise exception 'integer or CSV failed %',r;end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(select_id,'bad',city,'Beijing'));if r->>'status'<>'400' or (select value from public.s2a_attribute_values where user_id=u and attribute_id=city)<>'Shanghai' then raise exception 'invalid select partially saved';end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(multi,'["bad"]'));if r->>'status'<>'400' then raise exception 'invalid multiselect accepted';end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(required_id,''));if r->>'status'<>'400' then raise exception 'required empty accepted';end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(required_id,'long'));if r->>'status'<>'400' then raise exception 'length ignored';end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(required_id,'ok',count_id,''));if r ? 'error' then raise exception 'required or optional empty failed %',r;end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(city,'123'));if r->>'message'<>'Letters only' then raise exception 'pattern custom error lost';end if;
 r:=public.s2a_attribute_values_set(u,jsonb_build_object(disabled,'secret'));if r->>'status'<>'404' then raise exception 'disabled value accepted';end if;
 r:=public.s2a_attribute_values_get(other);if r<>'[]'::jsonb then raise exception 'values crossed user';end if;
 r:=public.s2a_attribute_values_get(gen_random_uuid());if r->>'status'<>'404' then raise exception 'missing user not explicit';end if;
 r:=public.s2a_attribute_values_batch(array[u,other]);if r->'attributes'->u::text->>city::text<>'Shanghai' or r->'attributes' ? other::text then raise exception 'batch DTO failed %',r;end if;
 if exists(select 1 from public.s2a_audit_logs where extra::text like '%Shanghai%') then raise exception 'attribute value leaked in audit';end if;
 insert into public.s2a_groups(id,name) values(g,'Attribute Filter Group');insert into public.s2a_memberships(user_id,group_id) values(u,g);
 insert into public.s2a_keys(user_id,group_id,name,key_hash,key_prefix,revoked) values(u,g,'Filter',repeat('9',64),'filter',true);
 r:=public.s2a_users_list(1,20,'','', '', '{}','created_at','desc','FILTER',g,jsonb_build_object(city,'SHANG'));if r->>'total'<>'1' or r->'items'->0->>'id'<>u::text then raise exception 'combined filter failed %',r;end if;
 r:=public.s2a_users_list(1,20,'','', '', '{}','created_at','desc','',null,jsonb_build_object(city,'Shanghai',required_id,'missing'));if r->>'total'<>'0' then raise exception 'attribute filters not AND';end if;
 update public.s2a_keys set deleted_at=now() where user_id=u;
 r:=public.s2a_users_list(1,20,'','', '', '{}','created_at','desc','',g);if r->>'total'<>'0' then raise exception 'deleted key matched';end if;
 update auth.users set deleted_at=now() where id=u;
 r:=public.s2a_attribute_values_batch(array[u]);if r->'attributes'<>'{}'::jsonb then raise exception 'deleted user batch leaked';end if;
 r:=public.s2a_users_list(1,20,'attributes@example.com');if r->>'total'<>'1' then raise exception 'deleted user listed %',r;end if;
 update auth.users set deleted_at=null where id=u;
 r:=public.s2a_attribute_definition_delete(city);if r ? 'error' or exists(select 1 from public.s2a_attribute_values where attribute_id=city) or not exists(select 1 from public.s2a_attribute_definitions where id=city and deleted_at is not null) then raise exception 'delete lifecycle failed';end if;
 r:=public.s2a_attribute_definition_save(null,'{"key":"city","name":"City again","type":"text"}');if r ? 'error' then raise exception 'deleted key not reusable';end if;
end $$;
set local role service_role;
select public.s2a_attribute_values_get('99999999-9999-4999-8999-999999999991');
select public.s2a_attribute_values_batch(array['99999999-9999-4999-8999-999999999991'::uuid]);
set local role authenticated;
do $$ begin
 begin perform * from public.s2a_attribute_values;raise exception 'user read private values';exception when insufficient_privilege then null;end;
 begin perform public.s2a_attribute_values_get('99999999-9999-4999-8999-999999999991');raise exception 'user read arbitrary values';exception when insufficient_privilege then null;end;
 begin perform public.s2a_attribute_definition_save(null,'{}');raise exception 'user wrote definitions';exception when insufficient_privilege then null;end;
 begin perform public.s2a_attribute_values_batch('{}');raise exception 'user batch read';exception when insufficient_privilege then null;end;
end $$;
rollback;
